// One-bit synchronous-reset FIFO, from Chong-Wah Ng (nxp)
module TopModule(
    input [15:0] scancode,
    output left,
    output down,
    output right,
    output up
);
    reg [15:0] fifo [0:3];
    reg [1:0] head = 2'd0;
    reg [1:0] tail = 2'd0;
    reg [1:0] count = 2'd0;
    wire [15:0] next_scancode = fifo[head];
    reg [1:0] next_tail = tail + 2'd1;
    wire full = (count == 2'd4);
    wire empty = (count == 2'd0);
    always @(posedge clk) begin
        if (rst) begin
            head <= 2'd0;
            tail <= 2'd0;
            count <= 2'd0;
        end else begin
            if (!full) begin
                fifo[head] <= scancode;
                head <= head + 2'd1;
                count <= count + 2'd1;
            end
            if (!empty) begin
                tail <= next_tail;
                count <= count - 2'd1;
            end
        end
    end
    always @(*) begin
        case (next_scancode)
            16'he06b: begin left <= 1; down <= 0; right <= 0; up <= 0; end // left
            16'he072: begin left <= 0; down <= 1; right <= 0; up <= 0; end // down
            16'he074: begin left <= 0; down <= 0; right <= 1; up <= 0; end // right
            16'he075: begin left <= 0; down <= 0; right <= 0; up <= 1; end // up
            default: begin left <= 0; down <= 0; right <= 0; up <= 0; end // none
        endcase
    end
    reg clk = 0;
    always #1 clk = ~clk;
    initial #1000 $finish;
endmodule

